import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test("Update a draft vendor", { tag: "@VEN-08" }, async ({ apiAs }) => {
    // Background: signed in as member@northwind.test
    const member = await apiAs("member");

    // Given a vendor in status "draft"
    const created = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Acme Freight"),
        category: "logistics",
        contact_email: "ops@acmefreight.example",
      },
    });
    expect(created.status()).toBe(201);
    const vendor = await created.json();
    expect(vendor.status).toBe("draft");

    // When I change its contact email to "billing@acmefreight.example"
    const updated = await member.patch(`/api/vendors/${vendor.id}`, {
      data: { contact_email: "billing@acmefreight.example" },
    });

    // Then the response status is 200
    expect(updated.status()).toBe(200);
    const body = await updated.json();
    expect(body.id).toBe(vendor.id);
    expect(body.contact_email).toBe("billing@acmefreight.example");

    // And an audit event "vendor.updated" is recorded
    const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
    expect(audit.status()).toBe(200);
    const trail = (await audit.json()) as { items: { action: string }[] };
    expect(trail.items.map((event) => event.action)).toContain("vendor.updated");
  });
});
